// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager(address(this));
    }

    function _run(bytes32 assertionId, bool assertedTruthfully) internal {
        vm.assume(true);
        bool reverted;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(bytes32 assertionId, bool assertedTruthfully) public {
        _run(assertionId, assertedTruthfully);
    }

    receive() external payable {}
}
